function Button({children,onClick,primary=false,quiet=false,className='',type='button',disabled=false}:{children:ReactNode;onClick?:()=>void;primary?:boolean;quiet?:boolean;className?:string;type?:'button'|'submit';disabled?:boolean}){return <button type={type} disabled={disabled} className={`${primary?'btn primary':quiet?'btn quiet':'btn'} ${className}`} onClick={onClick}>{children}</button>}
